import { IconArrowDown, IconArrowUp, type IconProps } from '@hawkins/assets';

import styles from './index.module.css';

export const getDiffClassname = (value: number | undefined): string => {
    if (value === undefined) {
        return styles.undefined;
    }
    if (value === 0) {
        return styles.neutral;
    }
    if (value === undefined || value === 0) {
        return styles.neutral;
    }
    if (value < 0) {
        return styles.negative;
    }
    return styles.positive;
};

export const getDiffIcon = (value: number | undefined, size: IconProps['size']) => {
    if (value === undefined || value === 0) {
        return null;
    }
    if (value < 0) {
        return <IconArrowDown size={size} className={getDiffClassname(value)} />;
    }
    return <IconArrowUp height={size} className={getDiffClassname(value)} />;
};

export const getDiffValue = (value: number | undefined) => {
    if (value === undefined) {
        return '';
    }

    if (Math.abs(value) > 0) {
        return `${value > 0 ? '+' : ''}${value.toLocaleString()}`;
    }
    return value;
};

export const formatNumberShort = (num: number | undefined): string => {
    if (!num) {
        return '0';
    }
    return new Intl.NumberFormat('en', {
        notation: 'compact',
        compactDisplay: 'short',
        maximumFractionDigits: 2,
    }).format(num);
};
