import { type ErrorCodeConfig, ErrorCodeTypes } from './constants';

export const getErrorConfigFromCode = (errorCode: string | undefined): ErrorCodeConfig | undefined => {
    const regex = /^(\d+)\.\d+-(.+)$/;
    const match = errorCode?.match(regex);
    let result: ErrorCodeConfig | undefined;

    if (match) {
        const firstNumber = match[1];
        let type: string | undefined;
        const code = Number(firstNumber);

        ErrorCodeTypes.forEach((typeConfig) => {
            if (typeConfig.range[0] <= code && typeConfig.range[1] >= code) {
                result = typeConfig;
            }
        });
    }

    return result;
};

