import type { FunctionComponent, ReactNode } from 'react';
import { Card, Divider, Loader, Heading, Text, TextLink } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import VizTimeSeries, { type VizTimeSeriesProps } from './VizTimeseries';
import styles from './ChartTile.module.css';

export interface ChartTileProps {
    title: string | ReactNode;
    subtitle: string | ReactNode;
    timeSeriesProps: VizTimeSeriesProps;
    loading?: boolean;
    filterProps: {
        filterRenderer: React.ReactNode;
        categoriesHiddenByFilter?: number;
        onResetFilters: () => void;
    };
    /** Component to render in the righthand header before the "reset filters link" */
    rightHeaderGroup?: React.ReactNode;
}

const ChartTile: FunctionComponent<ChartTileProps> = ({
    title,
    subtitle,
    rightHeaderGroup,
    timeSeriesProps,
    filterProps: { filterRenderer, onResetFilters, categoriesHiddenByFilter },
    loading = false,
}) => {
    return (
        <Card className={styles.root}>
            <div className={styles.header}>
                <div>
                    <Heading level={0}>{title}</Heading>
                    <Text variant='body' level={1} colorVariant='faded' component='div'>
                        {subtitle}
                    </Text>
                </div>
                <div className={styles.filterContainer}>
                    {rightHeaderGroup}
                    {rightHeaderGroup && !!categoriesHiddenByFilter && <Divider variant='vertical' color='xLight' />}
                    {!!categoriesHiddenByFilter && categoriesHiddenByFilter > 0 && (
                        <div className={styles.resetFilterContainer}>
                            <Text bold variant='label' colorVariant='faded' level={0} component='div'>
                                {categoriesHiddenByFilter} Hidden
                            </Text>
                            <TextLink
                                bold
                                className={styles.resetLink}
                                data-testid='clear-filters-button'
                                onClick={onResetFilters}
                            >
                                Show All
                            </TextLink>
                        </div>
                    )}
                    {filterRenderer}
                </div>
            </div>
            {loading ? (
                <div className={styles.loaderContainer}>
                    <Loader size={Dimensions.Size48} />
                </div>
            ) : (
                <VizTimeSeries {...timeSeriesProps} />
            )}
        </Card>
    );
};

export default ChartTile;
