import { createContext, useContext, useState, type ReactNode } from 'react';
import type { ErrorCodeType } from '../utils/constants';

interface HighlightedCrashTypesContextValue {
    highlightedType: ErrorCodeType | undefined;
    setHighlightedType: (type: ErrorCodeType | undefined) => void;
}

const HighlightedCrashTypesContext = createContext<HighlightedCrashTypesContextValue | undefined>(undefined);

export function HighlightedCrashTypesProvider({ children }: { children: ReactNode }) {
    const [highlightedType, setHighlightedType] = useState<ErrorCodeType | undefined>();

    return (
        <HighlightedCrashTypesContext.Provider value={{ highlightedType, setHighlightedType }}>
            {children}
        </HighlightedCrashTypesContext.Provider>
    );
}

export function useHighlightedCrashTypes() {
    const context = useContext(HighlightedCrashTypesContext);
    if (context === undefined) {
        throw new Error('useHighlightedCrashTypes must be used within a HighlightedCrashTypesProvider');
    }
    return context;
}
