import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';

export const COREDUMPS_QUERY_KEY = 'coredumps';

export interface Coredump {
    gsId: string;
    dedupId: string;
    gameId: string;
    timestamp: string;
    machineId: string;
    application: string;
    message: string;
    environment: string;
}

export interface CoredumpsResponse {
    data?: Coredump[];
    errors?: any;
}

export const useCoredumps = (startDate: string, endDate: string, gameId: string | undefined) => {
    const query = useQuery<CoredumpsResponse>({
        queryKey: [COREDUMPS_QUERY_KEY, startDate, endDate, gameId],
        gcTime: 0,
        enabled: !!startDate && !!endDate && !!gameId,

        queryFn: async () => {
            const response = await fetch('/api/coredumps', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    startDate,
                    endDate,
                    gameId,
                }),
            });
            return await response.json();
        },
    });

    const coredumps = useMemo(() => {
        return Array.isArray(query.data?.data) ? query.data?.data : [];
    }, [query]);

    return {
        ...query,
        coredumps,
    };
};
