import { useTheme } from '@hawkins/components';
import {
    CategoryLegend,
    CategoryLegendItem,
    useLinkedViz,
    useNormalizedProps,
    useVizkitContext,
    Viz,
    VizkitProvider,
} from '@netflix-internal/react-vizkit';
import { formatNumberShort } from './components/Summary/helpers';

interface CrashDashboardLegendProps {
    data: any;
    contextName: string;
    aggregates: any;
}

export const CrashDashboardLegend = ({ data, aggregates, contextName }: CrashDashboardLegendProps) => {
    const { onSendAction } = useLinkedViz({
        datasets: [],
        linkAccessor: 'dedupId', // actually unused since we highlight datasets
    });

    const vizkitContext = useVizkitContext();
    const theme = useTheme();

    const props = useNormalizedProps({ props: { data }, vizkitContext });

    return (
        <div style={{ position: 'absolute', left: 0, right: 0 }}>
            <VizkitProvider darkMode={theme.name === 'dark'}>
                <Viz
                    {...props}
                    height={0}
                    width={0}
                    margin={{ top: 0, left: 0, right: 0, bottom: 0 }}
                    contextName={contextName}
                    onSendAction={onSendAction}
                >
                    <CategoryLegend
                        xAlign='left'
                        layer='html-before'
                        position={null}
                        direction='column'
                        absolutePosition={false}
                        swatchShape='rounded'
                        render={(info) => {
                            const { title, index, ...other } = info;

                            return (
                                <CategoryLegendItem {...other}>
                                    {formatNumberShort(aggregates.get(title as string)?.gsIds.length!)}
                                </CategoryLegendItem>
                            );
                        }}
                    />
                </Viz>
            </VizkitProvider>
        </div>
    );
};
