import { DataVizColors } from '@hawkins/variables';
import type { ErrorCodeType } from './constants';

export const ERROR_TYPE_COLORS_DARK: Record<ErrorCodeType, string> = {
    user: DataVizColors.Dark.Categorical[1],
    ocga: DataVizColors.Dark.Categorical[2],
    displayDevice: DataVizColors.Dark.Categorical[4],
    controlPlane: DataVizColors.Dark.Categorical[3],
    gameControlError: DataVizColors.Dark.Categorical[5],
    ocgaCommunicationError: DataVizColors.Dark.Categorical[2],
    userError: DataVizColors.Dark.Categorical[7],
    controllerDevice: DataVizColors.Dark.Categorical[8],
    controllerPlaneServer: DataVizColors.Dark.Categorical[3],
    other: DataVizColors.Dark.Categorical[0],
    unidentified: DataVizColors.Dark.Gray[5],
};

export const ERROR_TYPE_COLORS_LIGHT: Record<ErrorCodeType, string> = {
    user: DataVizColors.Light.Categorical[1],
    ocga: DataVizColors.Light.Categorical[2],
    displayDevice: DataVizColors.Light.Categorical[4],
    controlPlane: DataVizColors.Light.Categorical[3],
    gameControlError: DataVizColors.Light.Categorical[5],
    ocgaCommunicationError: DataVizColors.Light.Categorical[2],
    userError: DataVizColors.Light.Categorical[7],
    controllerDevice: DataVizColors.Light.Categorical[8],
    controllerPlaneServer: DataVizColors.Light.Categorical[3],
    other: DataVizColors.Light.Categorical[0],
    unidentified: DataVizColors.Light.Gray[5],
};

export const getErrorTypeColor = (errorType: ErrorCodeType, theme: any): string => {
    const themeColors = theme.name === 'dark' ? ERROR_TYPE_COLORS_DARK : ERROR_TYPE_COLORS_LIGHT;
    return themeColors[errorType] || themeColors.unidentified;
};
