import { ROUTE_SESSIONS } from '@gsm-app/constants';
import { useSessionGameLogsErrors } from '@gsm-app/hooks/useSessionGameLogsErrors';
import { IconChevronLeft, IconChevronRight, IconLinkOut } from '@hawkins/assets';
import { Button, ButtonGroup, Heading, Loader, Stack, Text, VerticalList, VerticalListItem } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { useMemo, useState } from 'react';

export interface CrashGameLogsSummaryProps {
    gsIds?: string[];
}

export const CrashGameLogsSummary = (props: CrashGameLogsSummaryProps) => {
    const { gsIds } = props;
    const [sessionIndex, setSessionIndex] = useState(0);

    const gsId = useMemo(() => {
        return gsIds ? gsIds[sessionIndex] : undefined;
    }, [gsIds, sessionIndex]);

    const { errors, isLoading } = useSessionGameLogsErrors(gsId);

    const totalSessions = gsIds?.length || 0;

    return (
        <Stack style={{ height: Dimensions.Size448 }} gap={Dimensions.Space12}>
            <Stack orientation='horizontal' style={{ alignItems: 'center', justifyContent: 'space-between' }}>
                <Stack gap={Dimensions.Space6} orientation='horizontal' style={{ alignItems: 'center' }}>
                    <Heading level={1}>
                        {totalSessions > 0 ? `Crash Logs (${sessionIndex + 1} of ${totalSessions})` : 'Crash Logs'}
                    </Heading>
                    <Stack gap={Dimensions.Space6} orientation='horizontal' style={{ alignItems: 'center' }}>
                        <Button compact to={`${ROUTE_SESSIONS}/${gsId}`} target='_blank' variant='tertiary'>
                            <Text colorVariant='faded' variant='monospaced'>
                                {gsId}
                            </Text>
                            <IconLinkOut size='small' style={{ marginLeft: Dimensions.Space4 }} />
                        </Button>
                    </Stack>
                </Stack>

                <ButtonGroup>
                    <Button
                        variant='icon'
                        icon={IconChevronLeft}
                        disabled={sessionIndex === 0}
                        onClick={() => setSessionIndex(sessionIndex - 1)}
                    >
                        Previous Log
                    </Button>

                    <Button
                        variant='icon'
                        icon={IconChevronRight}
                        disabled={totalSessions === 0 || sessionIndex === totalSessions - 1}
                        onClick={() => setSessionIndex(sessionIndex + 1)}
                    >
                        Next Log
                    </Button>
                </ButtonGroup>
            </Stack>
            {isLoading ? (
                <Loader variant='circular' />
            ) : (
                <>
                    {errors.length > 0 ? (
                        <VerticalList style={{ maxHeight: 380, overflow: 'auto' }}>
                            {errors.map((log: any, index: number) => {
                                return (
                                    <VerticalListItem key={index}>{log.Message?.LogEvent?.Message}</VerticalListItem>
                                );
                            })}
                        </VerticalList>
                    ) : (
                        <Text colorVariant='faded'>No logs for this session</Text>
                    )}
                </>
            )}
        </Stack>
    );
};
