import { type Coredump, useCoredumps } from '@gsm-app/hooks/useCoredumps';
import { Content } from '@gsm-common/components/Content';
import { Layout } from '@gsm-common/components/Layout';
import { paramsObject, useSearchParams } from '@gsm-common/hooks/useSearchParams';
import { keyFromOptions } from '@gsm-common/utils/dropdown/keyFromOptions';
import { IconCircleI } from '@hawkins/assets';
import { Role } from '@ncgt/common/models/identity';
import {
    Card,
    DatePickerDropdown,
    Divider,
    Dropdown,
    type DropdownOption,
    Heading,
    Loader,
    Paper,
    Stack,
    Tag,
    Text,
    Tooltip,
    getFuzzyFilterOption,
    useTheme,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import {
    BarCursorLine,
    type DataConfig,
    HistogramChart,
    Rects,
    VizGroup,
    VizkitProvider,
    XYPopperPoint,
    Zoom,
    transformBin,
    transformStack,
    useHighlightDataset,
} from '@netflix-internal/react-vizkit';
import { forwardRef, useMemo, useState } from 'react';
import moment from 'moment-timezone';
import { DropdownTrigger } from '../Play/components/PageHeader/components/DropdownTrigger';
import { useGameChannels } from '../Play/hooks/useGameChannels';
import styles from './CrashDashboard.module.css';
import { CrashGameLogsSummary } from './CrashGameLogsSummary';
import { useSuccessfulSessions } from '@gsm-app/hooks/useSuccessfulSessions';
import SummaryTile from './components/Summary/SummaryTile';
import TodayTile from './components/Summary/TodayTile';
import SuccessfulSessionRatioChartTile from './components/SuccessfulSessionRatioChartTile';
import { CrashDashboardLegend } from './CrashDashboardLegend';
import { useFeature } from '@gsm-app/hooks/useFeature';
import { CrashCountsTable } from './CrashCountsTable';
import { CrashTypesHistogram } from './CrashTypesHistogram';
import { useIdentity } from '@gsm-app/providers/IdentityProvider';
import { HighlightedCrashTypesProvider } from './hooks/useHighlightedCrashTypes';

type SearchParams = { gameId?: string; channelName?: string; startDate?: string; endDate?: string };

type CoredumpSummary = {
    dedupId: string;
    gsIds: string[];
    builds: any[];
    timestamps: string[];
    environment: string;
};

const environmentOptions = [
    { label: 'DEV', value: 'DEV' },
    { label: 'STAGING', value: 'STAGING' },
    { label: 'PROD', value: 'PROD' },
];

export const CrashDashboard = () => {
    const { gameOptions, selectedGame } = useGameChannels();
    const { identity } = useIdentity();
    const isNCGTAdmin = identity.roles.has(Role.NCGT_ADMIN);

    const [environment, setEnvironment] = useState<DropdownOption<string>[] | undefined>();
    const [selectedBuildIds, setSelectedBuildIds] = useState<DropdownOption<string>[] | undefined>();
    const [
        {
            gameId,
            startDate = moment().utc().subtract(14, 'days').startOf('day').toISOString(),
            endDate = moment().utc().endOf('day').toISOString(),
        },
        setParams,
    ] = useSearchParams<SearchParams>();
    const theme = useTheme();
    const [clicked, setClicked] = useState<any>(null);

    const { isLoading, coredumps } = useCoredumps(startDate, endDate, gameId);
    const { successfulSessions: successfulSessionsEnabled } = useFeature();
    const { isLoading: isLoadingSuccessfulSessions, successfulSessions } = useSuccessfulSessions(
        startDate,
        endDate,
        gameId,
        successfulSessionsEnabled,
    );

    const todayISO = useMemo(() => {
        return moment().utc().endOf('day').toISOString();
    }, []);

    const datasets: any = [];

    const buildIdOptions = useMemo(() => {
        const applicationRegex = /\/games\/([^/]+)\/[^/]+$/;
        const buildIdMap = new Map<string, DropdownOption<string>>();
        coredumps?.forEach((c) => {
            const buildMatch = c.application.match(applicationRegex);
            const build = buildMatch && buildMatch.length >= 1 ? buildMatch[1] : '';
            if (!buildIdMap.has(build)) {
                buildIdMap.set(build, { label: build, value: build });
            }
        });
        return [...buildIdMap.values()];
    }, [coredumps]);

    const aggregates = useMemo(() => {
        const applicationRegex = /\/games\/([^/]+)\/[^/]+$/;
        const result = new Map<string, CoredumpSummary>();
        let y = 0;

        coredumps
            ?.filter((coredump) => {
                const coredumpEnvironment = coredump?.environment;
                if (environment && environment.length > 0) {
                    return environment.map((envOption) => envOption.value).includes(coredumpEnvironment);
                }
                return true;
            })
            .filter((coredump) => {
                const buildMatch = coredump.application.match(applicationRegex);
                const build = buildMatch && buildMatch.length >= 1 ? buildMatch[1] : '';
                if (selectedBuildIds && selectedBuildIds.length > 0) {
                    return selectedBuildIds.map((buildIdOption) => buildIdOption.value).includes(build);
                }

                return true;
            })
            .sort((a, b) => Number(a.timestamp) - Number(b.timestamp))
            .forEach((c: Coredump) => {
                const buildMatch = c.application.match(applicationRegex);
                const build = buildMatch && buildMatch.length >= 1 ? buildMatch[1] : '';
                if (!result.has(c.dedupId)) {
                    datasets.push({
                        title: `${coredumps.length}`,
                        points: [{ x: new Date(Number(c.timestamp) / 1000), y }],
                    });
                    result.set(c.dedupId, {
                        dedupId: c.dedupId,
                        gsIds: [c.gsId],
                        builds: [build],
                        timestamps: [c.timestamp],
                        environment: c.environment,
                    });
                } else {
                    const dedupSummary = result.get(c.dedupId);
                    dedupSummary?.gsIds.push(c.gsId);
                    if (!dedupSummary?.builds.includes(build)) {
                        dedupSummary?.builds.push(build);
                    }
                    dedupSummary?.timestamps.push(c.timestamp);
                    datasets[0].points.push({ x: new Date(Number(c.timestamp) / 1000), y });
                }
                y += 1;
            });

        return result;
    }, [coredumps, environment, selectedBuildIds]);

    // Charting values
    const data = useMemo(() => {
        const applicationRegex = /\/games\/([^/]+)\/[^/]+$/;
        const points =
            coredumps
                ?.filter((coredump: Coredump) => {
                    const coredumpEnvironment = coredump?.environment;
                    if (environment && environment.length > 0) {
                        return environment.map((envOption) => envOption.value).includes(coredumpEnvironment);
                    }
                    return true;
                })
                .filter((coredump) => {
                    const buildMatch = coredump.application.match(applicationRegex);
                    const build = buildMatch && buildMatch.length >= 1 ? buildMatch[1] : '';

                    if (selectedBuildIds && selectedBuildIds.length > 0) {
                        return selectedBuildIds.map((buildIdOption) => buildIdOption.value).includes(build);
                    }

                    return true;
                })
                .map((c, i) => {
                    return {
                        value: 1,
                        date: new Date(Number(c.timestamp) / 1000),
                        dedupId: c.dedupId,
                        gsId: c.gsId,
                        environment: c.environment,
                        id: i,
                    };
                }) || [];

        let data: DataConfig = {
            points,
            channels: {
                x: 'date',
                color: 'dedupId',
                dataset: 'dedupId',
                datasetTitle: 'dedupId',
            },
        };
        data = transformBin({ axis: 'x', y: 'count', thresholds: 20 }, data);
        data = transformStack({ axis: 'y' }, data);
        return data;
    }, [coredumps, selectedBuildIds, environment]);

    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayString = yesterday.toLocaleDateString();

    return (
        <Layout full>
            <Content style={{ padding: 0 }}>
                <Paper elevation={1} className={styles.headerBanner}>
                    <Dropdown
                        DropdownTrigger={forwardRef((props: any, ref: any) => (
                            <DropdownTrigger {...props} hideSubtitle ref={ref} />
                        ))}
                        label={`Game ID: ${selectedGame?.value ?? ''}`}
                        groupBy={(option) => option.group ?? ''}
                        onChange={(selected) => {
                            if (selected) {
                                setParams(
                                    (prev): SearchParams => {
                                        return {
                                            ...paramsObject(prev),
                                            gameId: selected.value,
                                            channelName: undefined,
                                        };
                                    },
                                    { replace: true },
                                );
                            }
                        }}
                        options={gameOptions}
                        loading={gameOptions.length === 0}
                        value={selectedGame}
                        getOptionValue={(option) => {
                            if (typeof option === 'string') {
                                return option;
                            }
                            return `${option.group}_${option.value}`;
                        }}
                        searchable={gameOptions.length > 5}
                        filterOptions={getFuzzyFilterOption(gameOptions, {
                            keys: ['label', 'subtitle'],
                            ignoreLocation: true,
                        })}
                        key={`games-${keyFromOptions(gameOptions)}`}
                        style={{ maxWidth: 230, width: 'auto' }}
                        dropdownWidthType={350}
                    />
                    <Stack orientation='horizontal' gap={Dimensions.Space8}>
                        <DatePickerDropdown
                            clearable
                            range
                            maxSelectableDate={todayISO}
                            selected={[
                                startDate ? moment.utc(startDate).format('YYYY-MM-DD') : startDate,
                                endDate ? moment.utc(endDate).format('YYYY-MM-DD') : endDate,
                            ]}
                            startingDate={startDate ? moment.utc(startDate).format('YYYY-MM-DD') : startDate}
                            onSelectedChange={(range) => {
                                setParams(
                                    (prev): SearchParams => {
                                        return {
                                            ...paramsObject(prev),
                                            startDate: moment.utc(range[0]).startOf('day').toISOString(),
                                            endDate: moment.utc(range[1]).endOf('day').toISOString(),
                                        };
                                    },
                                    { replace: true },
                                );
                            }}
                        />
                    </Stack>

                    {isLoading && (
                        <Loader
                            style={{
                                position: 'absolute',
                                bottom: -Dimensions.RawSpace12,
                                left: 0,
                            }}
                            ariaLiveStatus={{ loadedText: '', loading: true, loadingText: 'Loading Content' }}
                            variant='linear'
                        />
                    )}
                </Paper>

                {successfulSessionsEnabled && (
                    <Stack className={styles.summaryTilesWrapper} gap={Dimensions.Space8}>
                        <TodayTile
                            title='Daily Success Ratio'
                            loading={isLoadingSuccessfulSessions}
                            subtitle={yesterdayString}
                            latestVal={successfulSessions?.dau?.current || 0}
                            diffVal={successfulSessions?.dau?.current - successfulSessions?.dau?.previous || 0}
                            isPercent={true}
                        />
                        <SummaryTile
                            title='Weekly Success Ratio'
                            subtitle='Last 7 days'
                            loading={isLoadingSuccessfulSessions}
                            latestVal={successfulSessions?.wau?.current || 0}
                            diffVal={successfulSessions?.wau?.current - successfulSessions?.wau?.previous || 0}
                            data={successfulSessions?.wau?.points || []}
                            isPercent={true}
                        />
                        <SummaryTile
                            title='Monthly Success Ratio'
                            subtitle='Last 30 days'
                            loading={isLoadingSuccessfulSessions}
                            latestVal={successfulSessions?.mau?.current || 0}
                            diffVal={successfulSessions?.mau?.current - successfulSessions?.mau?.previous || 0}
                            data={successfulSessions?.mau?.points || []}
                            isPercent={true}
                        />
                    </Stack>
                )}

                <Stack
                    gap={Dimensions.Space24}
                    style={{
                        margin: Dimensions.Space24,
                    }}
                >
                    {successfulSessionsEnabled && (
                        <SuccessfulSessionRatioChartTile<any>
                            initialChartFilter={[]}
                            datasets={successfulSessions?.rates}
                            title='Cloud session success rate'
                            subtitle={
                                <Stack>
                                    <Text variant='body' level={1} colorVariant='faded' component='div'>
                                        <Tooltip label='The 90% minimum acceptable percentage of crash-free game sessions. A dip below this line indicates a stability issue that requires investigation.'>
                                            <Stack className={styles.graphLabelContainer}>
                                                Session Success Threshold: 90%
                                                <IconCircleI size='small' />
                                            </Stack>
                                        </Tooltip>
                                    </Text>
                                </Stack>
                            }
                            loading={isLoadingSuccessfulSessions}
                            totalCategories={0}
                            FilterRendererComponent={() => {
                                return null;
                            }}
                            filterRendererProps={{}}
                        />
                    )}


                    <HighlightedCrashTypesProvider>
                        <Card className={styles.chartCardRoot}>
                            <Card.Header className={styles.chartCardHeader}>
                                <Stack gap={Dimensions.Space4}>
                                    <Stack gap={Dimensions.Space8} orientation='horizontal'>
                                    <Heading level={0}>Crash counts</Heading>
                                    <Tag variant='outlined' color='UNKNOWN'>
                                        PREVIEW
                                    </Tag>

                                    </Stack>
                                    <Text variant='body' level={1} colorVariant='faded' component='div'>
                                        <Tooltip
                                            label={`Crashes are aggregated and grouped by error type.
                                                The error table shows an aggregate and `}
                                        >
                                            <Stack className={styles.graphLabelContainer}>
                                                Deduped native crashes
                                                <IconCircleI size='small' />
                                            </Stack>
                                        </Tooltip>
                                    </Text>

                                </Stack>

                            </Card.Header>

                            <Card.Body style={{ padding: 0, minHeight: Dimensions.Size224 }}>
                                <CrashTypesHistogram
                                    startDate={startDate}
                                    endDate={endDate}
                                    gameId={gameId}
                                    successfulSessionsEnabled={successfulSessionsEnabled}
                                />
                            </Card.Body>
                        </Card>


                        <Card className={styles.chartCardRoot}>
                            <Card.Body style={{ padding: 0, minHeight: Dimensions.Size224 }}>
                                <CrashCountsTable
                                    startDate={startDate}
                                    endDate={endDate}
                                    gameId={gameId}
                                    successfulSessionsEnabled={successfulSessionsEnabled}
                                />
                            </Card.Body>
                        </Card>
                    </HighlightedCrashTypesProvider>

                    {/* Crash counts graph */}
                    {isNCGTAdmin && (
                        <Card className={styles.chartCardRoot}>
                            <Card.Header className={styles.chartCardHeader}>
                                <div>
                                    <Heading level={0}>Crash counts</Heading>
                                    <Text variant='body' level={1} colorVariant='faded' component='div'>
                                        <Tooltip
                                            label={`Crashes are aggregated and grouped based
                                                on the underlying exception. Click on a group
                                                to inspect individual logs, when available`}
                                        >
                                            <Stack className={styles.graphLabelContainer}>
                                                Deduped native crashes
                                                <IconCircleI size='small' />
                                            </Stack>
                                        </Tooltip>
                                    </Text>
                                </div>
                                <div className={styles.chartCardFilterContainer}>
                                    <Dropdown<DropdownOption<string>>
                                        multi
                                        compact
                                        clearable
                                        value={selectedBuildIds}
                                        onChange={(
                                            newValue: DropdownOption<string>[] | null,
                                            evt?: React.KeyboardEvent | React.MouseEvent,
                                        ) => {
                                            newValue ? setSelectedBuildIds(newValue) : setSelectedBuildIds(undefined);
                                        }}
                                        options={buildIdOptions}
                                        placeholder='Build Ids'
                                    />
                                    <Dropdown<DropdownOption<string>>
                                        multi
                                        clearable
                                        compact
                                        value={environment}
                                        onChange={(
                                            newValue: DropdownOption<string>[] | null,
                                            evt?: React.KeyboardEvent | React.MouseEvent,
                                        ) => {
                                            newValue ? setEnvironment(newValue) : setEnvironment(undefined);
                                        }}
                                        options={environmentOptions}
                                        placeholder='Env'
                                    />
                                </div>
                            </Card.Header>

                            {gameId !== '0' && !!coredumps && (
                                <Card.Body style={{ padding: 0 }}>
                                    {!isLoading && !coredumps.length && (
                                        <Stack gap={Dimensions.Space8}>
                                            <Heading level={2}>No crashes reported for this game</Heading>
                                            <Text colorVariant='faded'>
                                                Try a different game or specify a different date range
                                            </Text>
                                        </Stack>
                                    )}
                                    {!isLoading && coredumps.length > 0 && (
                                        <Stack>
                                            <Stack
                                                orientation='horizontal'
                                                gap={Dimensions.Space24}
                                                layout={{
                                                    display: 'flex',
                                                    flexDirection: 'row',
                                                    justifyContent: 'stretch',
                                                }}
                                            >
                                                <div className={styles.graphContainer}>
                                                    <Stack>
                                                        <VizkitProvider darkMode={theme.name === 'dark'}>
                                                            <HistogramChart
                                                                data={data}
                                                                contextName={{ actions: 'coredumps' }}
                                                                height={Dimensions.RawSize224}
                                                                width='100%'
                                                                disableGroups={['CategoryLegend']}
                                                                x={{
                                                                    type: 'utc',
                                                                    formatter: {
                                                                        tooltip: (date: Date) => {
                                                                            return `${date.toLocaleDateString()} ${date.toLocaleTimeString()}`;
                                                                        },
                                                                        axis: 'default',
                                                                    },
                                                                }}
                                                                y={{
                                                                    title: 'Count',
                                                                }}
                                                                touchPadProps={{
                                                                    onClick: (d: any) => {
                                                                        setClicked(d);
                                                                    },
                                                                }}
                                                            >
                                                                <Zoom />

                                                                <XYPopperPoint
                                                                    xType='contextual'
                                                                    yType='metric'
                                                                    xValueVariant='range'
                                                                    customize={(_info: any, current: any) => {
                                                                        return {
                                                                            ...current,
                                                                            title: (
                                                                                <span
                                                                                    style={{
                                                                                        textOverflow: 'ellipsis',
                                                                                        overflow: 'hidden',
                                                                                        maxWidth: 300,
                                                                                        display: 'block',
                                                                                    }}
                                                                                >
                                                                                    {current.title}
                                                                                </span>
                                                                            ),
                                                                        };
                                                                    }}
                                                                />

                                                                <VizGroup
                                                                    layer='svg-viz-fg'
                                                                    position='center'
                                                                    name='HighlightRects'
                                                                    render={(viz) => {
                                                                        const highlightDataset = useHighlightDataset();
                                                                        if (!highlightDataset) {
                                                                            return null;
                                                                        }

                                                                        return (
                                                                            <g>
                                                                                <Rects.Inner
                                                                                    insetLeft={1}
                                                                                    strokeWidth={2}
                                                                                    stroke={theme.Border}
                                                                                    filterDatasets={(dataset) =>
                                                                                        dataset === highlightDataset
                                                                                    }
                                                                                />
                                                                            </g>
                                                                        );
                                                                    }}
                                                                />
                                                                <BarCursorLine
                                                                    name='ClickedBarCursorLine'
                                                                    points={clicked?.points ?? null}
                                                                    lineWidth={1}
                                                                    layer='svg-viz-bg'
                                                                    lineOffsetWidth={4}
                                                                />
                                                            </HistogramChart>
                                                        </VizkitProvider>
                                                    </Stack>
                                                </div>

                                                <div className={styles.legendContainer}>
                                                    <CrashDashboardLegend
                                                        data={data}
                                                        aggregates={aggregates}
                                                        contextName='coredumps'
                                                    />
                                                </div>
                                            </Stack>

                                            <Divider className={styles.chartCardDivider} />

                                            {clicked?.points?.[0]?.d ? (
                                                clicked?.points?.[0]?.d.children[0]?.gsId && (
                                                    <CrashGameLogsSummary
                                                        gsIds={clicked?.points?.[0]?.d.children.map((c: any) => c.gsId)}
                                                    />
                                                )
                                            ) : (
                                                <Text colorVariant='faded' style={{ marginTop: Dimensions.Space12 }}>
                                                    Select entries from the graph to inspect session details
                                                </Text>
                                            )}
                                        </Stack>
                                    )}
                                </Card.Body>
                            )}
                        </Card>
                    )}
                </Stack>
            </Content>
        </Layout>
    );
};
