import { IconLinkOut } from '@hawkins/assets';
import { Button, ContextualBanner, Heading, Panel, Stack, Tag, Text, Tooltip, usePanelState, useTheme, VerticalList, VerticalListItem } from '@hawkins/components';
import {
    type AgGridReact,
    AllCommunityModule,
    type ColDef,
    type ColGroupDef,
    ColumnsToolPanelModule,
    FiltersToolPanelModule,
    type ICellRendererParams,
    MenuModule,
    SetFilterModule,
    SideBarModule,
    TableNext,
} from '@hawkins/table-next';
import { Dimensions } from '@hawkins/variables';
import { useCallback, useMemo, useRef, useState } from 'react';
import { PAGINATION_OPTIONS, PAGINATION_PAGE_SIZE, ROUTE_SESSIONS } from '../../constants';
import { useSuccessfulSessions, type CrashCountEntry } from '../../hooks/useSuccessfulSessions';
import { formatNumberShort } from './components/Summary/helpers';
import { getErrorConfigFromCode, getErrorTypeColor } from './utils';
import { useHighlightedCrashTypes } from './hooks/useHighlightedCrashTypes';
import type { ErrorCodeType } from './utils/constants';
interface CrashCountsTableProps {
    startDate: string;
    endDate: string;
    gameId: string | undefined;
    successfulSessionsEnabled: boolean;
}

export function CrashCountsTable(props: CrashCountsTableProps) {
    const {
        startDate,
        endDate,
        gameId,
        successfulSessionsEnabled,
    } = props;

    const gridRef = useRef<AgGridReact<CrashCountEntry>>(null);

    const [isOpen, state, { close, open, setState }] = usePanelState();
    const [crashDetailsGsids, setCrashDetailsGsids] = useState<string[] | undefined>();
    const { setHighlightedType } = useHighlightedCrashTypes();

    const modules = useMemo(
        () => [
            AllCommunityModule,
            SetFilterModule,
            MenuModule,
            SideBarModule,
            ColumnsToolPanelModule,
            FiltersToolPanelModule,
        ],
        [],
    );

    const { isLoading, error, successfulSessions } = useSuccessfulSessions(
        startDate,
        endDate,
        gameId,
        successfulSessionsEnabled,
    );

    const onToggleCrashDetails = useCallback((gsids?: string[]) => {
        setCrashDetailsGsids(gsids);
        open();
    }, [open]);

    const errorMessage = (error as any)?.message;

    const theme = useTheme();

    const columnDefs = useMemo<(ColDef<CrashCountEntry> | ColGroupDef<CrashCountEntry>)[]>(() => {
        return [
            {
                field: 'error_code',
                headerName: 'Error Code ⓘ',
                minWidth: Dimensions.RawSize224,
                flex: 1,
                headerTooltip: 'Unique codes associated with the error'
            },
            {
                field: 'error_code',
                headerName: 'Type ⓘ',
                flex: 1,
                minWidth: Dimensions.RawSize224,
                headerTooltip: 'Categorization of the error. Where it originated',
                filterValueGetter: (params) => {
                    return getErrorConfigFromCode(params.data?.error_code)?.type;
                },
                cellRenderer: (params: ICellRendererParams<CrashCountEntry, string>) => {
                    const errorTypeConfig = getErrorConfigFromCode(params.data?.error_code);
                    const errorType = errorTypeConfig?.type || 'unidentified';
                    const tagColor = getErrorTypeColor(errorType, theme);

                    return (
                        <Tooltip label={errorTypeConfig?.explanation || ''}>
                            <Tag
                                style={{ backgroundColor: theme.SurfaceBackgroundColor2, color: tagColor }}
                                onMouseEnter={() => setHighlightedType(errorType as ErrorCodeType)}
                                onMouseLeave={() => setHighlightedType(undefined)}
                            >
                                {errorType}
                            </Tag>
                        </Tooltip>
                    );

                }
            },
            {
                field: 'total_sessions_affected',
                headerName: 'Affected Sessions ⓘ',
                headerTooltip: 'Number of sessions that exhibited the error',
                cellRenderer: (params: ICellRendererParams<CrashCountEntry, number>) => {
                    return formatNumberShort(params.value as number)
                }
            },
            {
                field: 'percent_affected',
                filter: 'agNumberColumnFilter',
                headerName: '% of Total ⓘ',
                headerTooltip: 'Percentage of the total sessions that exhibited the error',
                width: 156,
            },
            {
                field: 'sample_sessions',
                headerName: 'Sample Sessions Ids ⓘ',
                flex: 1,
                headerTooltip: 'Sample game session ids to inspect logs in the session viewer',
                cellRenderer: (params: ICellRendererParams<CrashCountEntry, string | undefined>) => {
                    const sessionsRaw = params.value;
                    const gsids = sessionsRaw?.split('\\n') || [];

                    return gsids.length > 0 ? (
                        <Button variant='secondary' compact onClick={() => {
                            onToggleCrashDetails(gsids);
                        }}>
                            {gsids.length} Samples
                        </Button>
                    ) : null;
                }
            }
        ];
    }, [onToggleCrashDetails, theme, setHighlightedType]);

    const defaultColDef = useMemo<ColDef>(() => {
        return {
            editable: false,
            filter: true,
            floatingFilter: true,
            minWidth: 100,
            resizable: true,
            sortable: true,
        };
    }, []);

    const autoGroupColumnDef = useMemo<ColDef>(() => {
        return {
            cellRendererParams: {
                checkbox: false,
                suppressCount: false,
            },
            headerName: 'Group',
            menuTabs: [],
            minWidth: 250,
        };
    }, []);

    return (
        <div
            data-testid='crash-counts-table'
            style={{
                display: 'flex',
                flexDirection: 'column',
                height: Dimensions.Size448,
                flex: 1,
                width: '100%',
            }}
        >
            <Panel open={isOpen} position='right' state={state}  >
                <Panel.Header onCloseClick={close} onMaximizeClick={setState} onMinimizeClick={setState} title='Game Crash Details' />
                <Panel.Content>
                    <Stack gap={Dimensions.Space24}>
                        <Text colorVariant='faded'>
                            View detailed information about the selected crash entry.

                        </Text>

                        <VerticalList>
                            <Heading style={{
                                marginBottom: Dimensions.Space8
                            }} level={1}>Affected Sessions</Heading>
                            {crashDetailsGsids?.map((gsid: string) => {
                                return (
                                    <VerticalListItem key={gsid} >
                                        <Stack orientation='horizontal' layout={{
                                            justifyContent: 'space-between',
                                            alignItems: 'stretch',
                                            flex: 1
                                        }} gap={Dimensions.Space8} >
                                            <Text >{gsid}</Text>

                                            <Button compact icon={IconLinkOut} to={`${ROUTE_SESSIONS}/${gsid}`} target='_blank' tooltipLabel='Full logs' variant='icon'>
                                                Full logs
                                            </Button>
                                        </Stack>
                                    </VerticalListItem>
                                );
                            })}
                        </VerticalList>

                    </Stack>
                </Panel.Content>
            </Panel>
            {errorMessage ? (
                <ContextualBanner variant='error' text={errorMessage} />
            ) : (
                <TableNext<CrashCountEntry>
                    animateRows={true}
                    loading={isLoading}
                    autoGroupColumnDef={autoGroupColumnDef}
                    columnDefs={columnDefs}
                    enableCellTextSelection={true}
                    ensureDomOrder={true}
                    defaultColDef={defaultColDef}
                    gridRef={gridRef}
                    groupDefaultExpanded={1}
                    modules={modules}
                    noRowsOverlayComponent={() => <Text>No crash data available for the selected date range</Text>}
                    pagination={true}
                    paginationPageSize={PAGINATION_PAGE_SIZE}
                    paginationPageSizeSelector={PAGINATION_OPTIONS}
                    rowData={successfulSessions?.errorCounts}
                    style={{ height: '100%', width: '100%' }}
                />
            )}
        </div>
    );
}
