export type ErrorCodeType =
    | 'unidentified'
    | 'other'
    | 'user'
    | 'ocga'
    | 'displayDevice'
    | 'controlPlane'
    | 'gameControlError'
    | 'ocgaCommunicationError'
    | 'userError'
    | 'controllerDevice'
    | 'controllerPlaneServer';

export interface ErrorCodeConfig {
    range: [number, number];
    type: ErrorCodeType;
    explanation: string;
}

