import { type ReactNode, useEffect, useState } from 'react';

import ChartTile from './ChartTile';

type SuccessfulSessionRatioChartTileProps<TFilterComponentProps> = {
    datasets: any | undefined;
    title?: string | ReactNode;
    subtitle?: string | ReactNode;
    entitiesFallback?: string[] | null;
    totalCategories: number;
    FilterRendererComponent: React.ComponentType<
        TFilterComponentProps & {
            chartFilter: string[];
            setChartFilter: (val: string[]) => void;
        }
    >;
    filterRendererProps: TFilterComponentProps;
    initialChartFilter: string[];
    loading: boolean;
};

export const SYNC_ID = 'successfulSessions';

export const SuccessfulSessionRatioChartTile = <TFilterComponentProps extends object>(props: SuccessfulSessionRatioChartTileProps<TFilterComponentProps>) => {
    const {
        FilterRendererComponent,
        filterRendererProps,
        datasets,
        title,
        subtitle,
        totalCategories,
        entitiesFallback,
        loading,
        initialChartFilter,
    } = props;
    const [chartFilter, setChartFilter] = useState(initialChartFilter);
    useEffect(() => {
        setChartFilter(initialChartFilter);
    }, [initialChartFilter]);

    const entities = chartFilter?.length ? chartFilter : entitiesFallback || [];

    return (
        <ChartTile
            title={title}
            subtitle={subtitle}
            filterProps={{
                categoriesHiddenByFilter: totalCategories - entities.length,
                onResetFilters: () => setChartFilter([]),
                filterRenderer: (
                    <FilterRendererComponent
                        {...filterRendererProps}
                        chartFilter={chartFilter}
                        setChartFilter={setChartFilter}
                    />
                ),
            }}
            timeSeriesProps={{
                datasets,
                syncId: SYNC_ID
            }}
            loading={loading}
        />
    );
};
