import type { FunctionComponent } from 'react';

import { IconArrowDown, IconArrowUp } from '@hawkins/assets';
import { Card, Heading, Loader, Text, Tooltip } from '@hawkins/components';
import { DataVizColors } from '@hawkins/variables';

import { formatNumberShort, getDiffValue } from './helpers';
import SummaryChart from './SummaryChart';
import styles from './SummaryTile.module.css';

// For crash metrics, we invert the color logic: increase is bad (red), decrease is good (green)
const getDiffColor = (
    isCrashMetric: boolean,
    diffVal: number | undefined,
    negativeColor: string,
    positiveColor: string,
    grayColor: string,
): string => {
    if (diffVal === undefined || diffVal === 0) {
        return grayColor;
    }

    if (isCrashMetric) {
        return diffVal > 0 ? negativeColor : positiveColor;
    } else {
        return diffVal > 0 ? positiveColor : negativeColor;
    }
};

export interface SummaryTileProps {
    title: string;
    subtitle: string;
    latestVal: number | undefined;
    diffVal: number | undefined;
    isPercent?: boolean;
    data: {
        time: string;
        value: number;
    }[];
    isCrashMetric?: boolean;
    loading?: boolean;
}

const SummaryTile: FunctionComponent<SummaryTileProps> = ({
    title,
    subtitle,
    latestVal,
    diffVal,
    isPercent,
    data,
    isCrashMetric = false,
    loading = false,
}) => {
    const [negativeColor] = DataVizColors.Dark.Semantic.Negative;
    const [positiveColor] = DataVizColors.Dark.Semantic.Positive;
    const [grayColor] = DataVizColors.Dark.Gray;
    const diffColor = getDiffColor(isCrashMetric, diffVal, negativeColor, positiveColor, grayColor);

    const getDiffIcon = (value: number | undefined, size: 'small' | 'large' = 'large') => {
        if (!value) return null;
        const isPositive = value > 0;
        const Icon = isPositive ? IconArrowUp : IconArrowDown;
        return <Icon size={size} color={diffColor} />;
    };

    return (
        <Card className={styles.root} elevation={1}>
            <Card.Body className={styles.cardBody}>
                {loading ? (
                    <Loader
                        ariaLiveStatus={{
                            loadedText: '',
                            loading: true,
                            loadingText: 'Loading Content',
                        }}
                    />
                ) : (
                    <>
                        <div className={styles.header}>
                            <Text variant='body' level={2} bold>
                                {title}
                            </Text>
                            <Text variant='body' level={0} colorVariant='faded'>
                                {subtitle}
                            </Text>
                        </div>
                        <div className={styles.body}>
                            <div className={styles.leftContainer}>
                                <Heading level={3} className={styles.heading}>
                                    <Tooltip label={`${latestVal?.toLocaleString()}`}>
                                        {`${formatNumberShort(latestVal)}${isPercent ? '%' : ''}`}
                                    </Tooltip>
                                </Heading>
                                <div className={styles.diffHolder}>
                                    {getDiffIcon(diffVal, 'small')}
                                    <Text variant='body' level={1} color={diffColor}>
                                    {`${getDiffValue(diffVal)}${isPercent ? '%' : ''}`}
                                    </Text>
                                </div>
                            </div>
                            <div className={styles.chartContainer}>
                                <SummaryChart
                                    data={data}
                                    diffVal={diffVal || 0}
                                    latestVal={latestVal}
                                    isCrashMetric={isCrashMetric}
                                />
                            </div>
                        </div>
                    </>
                )}
            </Card.Body>
        </Card>
    );
};

export default SummaryTile;
