import { Areas, Lines, TimeSeries, YReferenceLine } from '@netflix-internal/react-vizkit';

import type { FunctionComponent } from 'react';
import { useGetSummaryVizData } from './useGetSummaryVizData';

export interface SummaryChartProps {
    data: any[];
    diffVal: number;
    latestVal?: number;
    isCrashMetric?: boolean;
}

const SummaryChart: FunctionComponent<SummaryChartProps> = ({ data, diffVal, latestVal, isCrashMetric = false }) => {
    const vizData = useGetSummaryVizData(data, diffVal, isCrashMetric);
    return (
        <TimeSeries
            datasets={vizData}
            width='100%'
            height='100%'
            margin={{
                top: 0,
                bottom: 0,
                left: 0,
            }}
            x={{ accessor: 'time' }}
            y={{ accessor: 'value' }}
            disableGroups={['LineHighlighted', 'XAxis', 'YAxis', 'XYGridLines', 'XYPopperLines', 'TouchPad']}
            spec={{
                y: {
                    formatter: () => '',
                },
            }}
        >
            <Areas
                strokeWidth={0}
                fillOpacity={[0.2 /* start opacity */, 0 /* end opacity */, 0.1 /* start position (10%) */]}
            />
            <YReferenceLine value={latestVal} hideValue />
            <Lines points='end' pointRadius={3} strokeWidth={1} />
        </TimeSeries>
    );
};

export default SummaryChart;
