import {
    CursorLine,
    deprecatedColors,
    getStyle,
    LineHighlighted,
    Lines,
    TimeSeries,
    type TimeSeriesProps,
    TooltipDiv,
    useHoverPoint,
    VizGroup,
    VizkitProvider,
    XYPopperLines,
    YReferenceLine,
} from '@netflix-internal/react-vizkit';
import { scaleOrdinal } from 'd3-scale';
import moment from 'moment-timezone';
import type { FunctionComponent } from 'react';

import { Divider, Stack, Text, useTheme } from '@hawkins/components';
import styles from './VizTimeseries.module.css';
import { Dimensions, Typography } from '@hawkins/variables';

export const getEndOfDay = (day: string) => {
    return moment(day).tz('UTC').endOf('day').toISOString();
};

export interface DateSetType {
    date: Date;
    value: number;
}

export interface DateSetSpec {
    title: string;
}

export interface TimeSeriesData {
    key: string;
    points: DateSetType[];
    spec: DateSetSpec;
}

export interface VizTimeSeriesProps {
    datasets: TimeSeriesData;
    /**
     * Provide the same syncId to multiple charts on a page to sync
     * their actions, eg. hover state, and their x-axis range
     */
    syncId?: string;
    /** default "count" - determines formatting of y-axis and tooltip values */
    yAxisMetric?: 'percent' | 'count';
}

/**
 * Vizkit TimeSeries with default props and settings applied for our use case
 */
const VizTimeSeries: FunctionComponent<VizTimeSeriesProps> = ({
    datasets,
    syncId = '',
    yAxisMetric = 'count',
}) => {
    const theme = useTheme();
    const spec: TimeSeriesProps<TimeSeriesData>['spec'] = {
        color: {
            accessor: 'key',
            on: 'dataset',
            scale: scaleOrdinal().range(deprecatedColors.hawkins.base),
        },
        x: {},
        y: {
            formatter: {
                tooltip: yAxisMetric === 'percent' ? (number) => `${number}%` : undefined,
            },
        },
    };

    return (
        <VizkitProvider darkMode={theme.name === 'dark'}>
            <TimeSeries
                className={styles.root}
                height={320}
                data={datasets}
                x={{
                    accessor: 'date',
                    type: 'utc',
                    domainPad: false,
                }}
                y={{
                    title: 'Success Session %',
                    domainMax: 100,
                    domainSoftSize: 0.5,
                    accessor: 'value',
                }}
                contextName={{ actions: syncId, xExtent: syncId }}
                disableGroups={['LineEndcaps', 'XYPopperLines']}
                spec={spec}
                margin={{
                    minBottom: 16,
                    minLeft: 36,
                }}
            >

                <Divider />
                <XYPopperLines highlightClosest hideNullish />
                <CursorLine highlightClosestPointToMouse />

                <Lines points='end' />
                <LineHighlighted points='end' />

                {/* Dashed line from start to first available data point */}
                <VizGroup
                    name='dashed-gap-line'
                    layer='svg-viz-fg'
                    position='center'
                    render={(viz) => {
                        // Find the first dataset
                        if (!datasets?.points || datasets?.points.length === 0) return null;

                        // Find the first point with a non-null value
                        const firstValidPointIndex = datasets?.points.findIndex((p) => p.value !== null);
                        if (firstValidPointIndex === -1 || firstValidPointIndex === 0) return null;

                        // Get the first date and the first valid point
                        const firstDate = datasets?.points[0].date;
                        const firstValidPoint = datasets?.points[firstValidPointIndex];

                        // Use vizkit's scale functions to convert data to screen coordinates
                        const x1 = viz.xScale ? viz.xScale(firstDate) : 0;
                        const y1 = viz.yScale ? viz.yScale(firstValidPoint.value) : 0;
                        const x2 = viz.xScale ? viz.xScale(firstValidPoint.date) : 0    ;
                        const y2 = viz.yScale ? viz.yScale(firstValidPoint.value) : 0;

                        return (
                            <line
                                x1={x1}
                                y1={y1}
                                x2={x2}
                                y2={y2}
                                stroke={deprecatedColors.hawkins.base[0]}
                                strokeWidth={2}
                                strokeDasharray='4 4'
                            />
                        );
                    }}
                />

                <VizGroup
                    name='tooltip-data-values'
                    layer='html-fg'
                    position='center'
                    hasPointerEvents={false}
                    render={() => {
                        const hoverPoint = useHoverPoint();
                        if (hoverPoint == null) return null;

                        const hoverTextColor = getStyle(['color', 'text'], hoverPoint);
                        return (
                            <TooltipDiv point={hoverPoint.d} centerY>
                                <Stack>
                                    <Text variant='label' colorVariant='faded'>
                                        {moment.utc(hoverPoint.d.date).format('MMM DD, YYYY')}
                                    </Text>
                                    <Text bold style={{ color: hoverTextColor }}>
                                        {hoverPoint.d.value?.toFixed(2) || ''}
                                    </Text>
                                </Stack>
                            </TooltipDiv>
                        );
                    }}
                />

                <YReferenceLine
                    value={90}
                    labelProps={{
                        fill: theme.Foreground,
                        fontSize: Typography.FontSize12,
                    }}
                    dx2={-Dimensions.RawSize112}
                    lineProps={{
                        stroke: theme.Foreground,
                        strokeWidth: Dimensions.BorderWidth2,
                    }}
                    label='Success threshold'
                    hideValue
                />
            </TimeSeries>
        </VizkitProvider>
    );
};

export default VizTimeSeries;
