import { useQuery } from '@tanstack/react-query';
import { useEffect, useMemo } from 'react';
import moment from 'moment-timezone';
import { createError } from '@gsm-common/utils/toast/createError';

export const SUCCESS_SESSION_KEY = 'success-sessions';

export interface SuccessfulSession {
    game_title_id: string;
    utc_date: string;
    total_cnt: number;
    error_cnt: number;
    unsuccessful_pct: number;
}

export interface CrashCountEntry {
    error_code: string;
    percent_affected: number;
    total_sessions_cnt: number;
    total_sessions_affected: number;
    sample_sessions: string;
    gsids?: string[];
}

export interface SuccessfulSessionResponse {
    data?: any[];
    errors?: any;
}

function getDateRange(start: Date, end: Date): Date[] {
    const dates: Date[] = [];
    const current = moment.utc(start).startOf('day');
    const endMoment = moment.utc(end);

    while (current.isSameOrBefore(endMoment)) {
        dates.push(current.toDate());
        current.add(1, 'day');
    }

    return dates;
}

export const useSuccessfulSessions = (
    startDate: string,
    endDate: string,
    gameId: string | undefined,
    enabled?: boolean,
) => {
    const query = useQuery<SuccessfulSessionResponse>({
        queryKey: [SUCCESS_SESSION_KEY, startDate, endDate, gameId],
        gcTime: 0,
        enabled: !!startDate && !!endDate && !!gameId && enabled,

        queryFn: async () => {
            const response = await fetch(`/api/games/${gameId}/success-sessions`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    startDate,
                    endDate,
                    gameId,
                }),
            });

            return await response.json();
        },
    });

    const successfulSessions = useMemo(() => {
        if (!query.data) {
            return {};
        } else {
            const [dau, wau, mau, ratesByDay, weeklyByDay, monthlyByDay, errorCounts, errorTypes] =
                query.data?.data ?? [];

            return {
                dau: {
                    current: dau?.[0]?.success_percentage,
                    previous: dau?.[1]?.success_percentage,
                    points: [],
                },
                wau: {
                    current: wau?.[0]?.success_percentage,
                    previous: wau?.[1]?.success_percentage,
                    points:
                        weeklyByDay?.map((entry: any) => ({
                            time: moment(entry.utc_date).toDate(),
                            value: entry.success_percentage || 100,
                        })) ?? [],
                },
                mau: {
                    current: mau?.[0]?.success_percentage,
                    previous: mau?.[1]?.success_percentage,
                    points:
                        monthlyByDay?.map((entry: any) => ({
                            time: moment(entry.utc_date).toDate(),
                            value: entry.success_percentage || 100,
                        })) ?? [],
                },
                rates: {
                    points: ratesByDay
                        ? getDateRange(
                              moment.utc(startDate).toDate(),
                              moment.utc(endDate).startOf('day').add(1, 'day').toDate(),
                          ).map((date: Date) => {
                              const value =
                                  ratesByDay.find((entry: any) => {
                                      const dateString = moment.utc(date).format('YYYYMMDD');
                                      return entry.utc_date === dateString;
                                  })?.success_percentage || null;
                              return {
                                  lineKey: 'rates',
                                  value: moment.utc(date).isAfter(moment.utc(endDate)) ? null : value,
                                  date,
                              };
                          })
                        : [],

                    channels: {
                        x: 'date',
                        y: 'value',
                        dataset: 'lineKey',
                        color: 'lineKey',
                        datasetTitle: (d: any) => {
                            return 'Success Session Ratio';
                        },
                    },
                },
                errorCounts,
                errorTypes,
            };
        }
    }, [startDate, endDate, query.data]);

    const { error, isError } = query;
    useEffect(() => {
        if (isError) {
            createError({
                title: 'Error Loading Successful sessions',
                body: `${error?.message}`,
                options: {
                    id: 'success-sessions-fetch-error',
                },
            });
        }
    }, [error, isError]);

    return {
        successfulSessions,
        ...query,
    };
};
