import { DataVizColors } from '@hawkins/variables';

export interface VizDateSetType {
    time: Date;
    value: number;
}

export interface VizDateSetSpec {
    color: string;
}

export interface VizData {
    points: VizDateSetType[];
    spec: VizDateSetSpec;
}

const getFillColor = (diffVal: number, isCrashMetric: boolean) => {
    if (diffVal === 0) {
        return DataVizColors.Dark.Gray[3];
    }

    // For crash metrics, increase is bad (red), decrease is good (green)
    // For engagement metrics, increase is good (green), decrease is bad (red)
    const isPositive = diffVal > 0;
    const isGood = isCrashMetric ? !isPositive : isPositive;

    return isGood ? DataVizColors.Dark.Semantic.Positive[1] : DataVizColors.Dark.Semantic.Negative[1];
};

const sortData = (data: any[]) => {
    return [...data].sort((a, b) => new Date(a.time).getTime() - new Date(b.time).getTime());
};

export const useGetSummaryVizData = (data: any[] | undefined, diffVal: number, isCrashMetric = false): VizData[] => {
    const dataset = {} as VizData;

    if (data) {
        dataset.points = [];
        dataset.spec = { color: getFillColor(diffVal, isCrashMetric) };

        const sorted = sortData(data);
        sorted.forEach((item) => {
            dataset.points.push({
                time: new Date(item.time),
                value: item.value,
            });
        });
    }

    return [dataset];
};

export default useGetSummaryVizData;
