import { ContextualBanner, Stack, useTheme } from '@hawkins/components';
import {
    BarCursorLine,
    CategoryLegend,
    type DataConfig,
    type Dataset,
    HistogramChart,
    Rects,
    VizGroup,
    VizkitProvider,
    XYPopperPoint,
    transformBin,
    transformStack,
    useHighlightDataset,
} from '@netflix-internal/react-vizkit';
import { Dimensions } from '@hawkins/variables';
import { useMemo, useState } from 'react';
import { useSuccessfulSessions } from '../../hooks/useSuccessfulSessions';
import moment from 'moment-timezone';
import { getErrorConfigFromCode, getErrorTypeColor } from './utils';
import type { ErrorCodeType } from './utils/constants';
import { useHighlightedCrashTypes } from './hooks/useHighlightedCrashTypes';

interface CrashTypesHistogramProps {
    startDate: string;
    endDate: string;
    gameId: string | undefined;
    successfulSessionsEnabled: boolean;
}

export function CrashTypesHistogram(props: CrashTypesHistogramProps) {
    const {
        startDate,
        endDate,
        gameId,
        successfulSessionsEnabled,
    } = props;

    const [clicked, setClicked] = useState<any>(null);
    const theme = useTheme();

    const { highlightedType, setHighlightedType } = useHighlightedCrashTypes();

    const { isLoading, error, successfulSessions } = useSuccessfulSessions(
        startDate,
        endDate,
        gameId,
        successfulSessionsEnabled,
    );

    const errorMessage = (error as any)?.message;

    const data = useMemo(() => {
        const start = moment.utc(startDate).startOf('day');
        const end = moment.utc(endDate).endOf('day');
        const daysDelta: Date[] = [];

        for (let current = start.clone(); current.isSameOrBefore(end, 'day'); current.add(1, 'day')) {
            daysDelta.push(current.toDate());
        }

        const points = successfulSessions?.errorTypes?.map((c: any, i: number) => {
            return {
                value: c.total_sessions_cnt,
                error_code: getErrorConfigFromCode(c.error_code)?.type || 'unidentified',
                date: moment(c.utc_date, 'YYYYMMDD').toDate(),
                id: i,
            };
        }) || [];

        let data: DataConfig = {
            points,
            channels: {
                x: 'date',
                dataset: 'error_code',
                datasetTitle: 'error_code',
                color: (d) => {
                    return getErrorTypeColor(d.error_code as ErrorCodeType, theme);
                }
            },
        };
        data = transformBin({ axis: 'x', y: 'count', thresholds: daysDelta as any[] }, data);
        data = transformStack({ axis: 'y' }, data);
        return data;

    }, [theme, successfulSessions, successfulSessions?.errorTypes, startDate, endDate]);

    const highlightedDataset = useMemo(() => {
        if (!highlightedType) {
            return undefined;
        }
        return {
            key: highlightedType,

        };
    }, [highlightedType]);

    return (
        <div
            data-testid='crash-types-table'
            style={{
                display: 'flex',
                flexDirection: 'column',
                flex: 1,
                width: '100%',
            }}
        >

            {errorMessage ? (
                <ContextualBanner variant='error' text={errorMessage} />
            ) : (
                <Stack>
                    <Stack
                        orientation='horizontal'
                        gap={Dimensions.Space24}
                        layout={{
                            display: 'flex',
                            flexDirection: 'row',
                            justifyContent: 'stretch',
                        }}
                    >
                        <VizkitProvider darkMode={theme.name === 'dark'}>
                            <HistogramChart
                                data={data}
                                contextName={{ actions: 'error_types' }}
                                height={Dimensions.RawSize224}
                                width='100%'
                                highlightDataset={highlightedDataset as Dataset<any>}
                                onHighlightDataset={(d) => {
                                    setHighlightedType(d?.key as ErrorCodeType | undefined);
                                }}
                                x={{
                                    type: 'utc',
                                    formatter: {
                                        tooltip: (date: Date) => {
                                            return `${date.toLocaleDateString()} ${date.toLocaleTimeString()}`;
                                        },
                                        axis: 'default',
                                    },
                                }}
                                y={{
                                    title: 'Count',
                                }}
                                touchPadProps={{
                                    onClick: (d: any) => {
                                        setClicked(d);
                                    },
                                }}
                            >
                                <XYPopperPoint
                                    xType='contextual'
                                    yType='metric'
                                    xValueVariant='range'
                                    customize={(_info: any, current: any) => {
                                        return {
                                            ...current,
                                            title: (
                                                <span
                                                    style={{
                                                        textOverflow: 'ellipsis',
                                                        overflow: 'hidden',
                                                        maxWidth: 300,
                                                        display: 'block',
                                                    }}
                                                >
                                                    {current.title}
                                                </span>
                                            ),
                                        };
                                    }}
                                />

                                <VizGroup
                                    layer='svg-viz-fg'
                                    position='center'
                                    name='HighlightRects'
                                    render={(viz) => {
                                        const highlightDataset = useHighlightDataset();
                                        if (!highlightDataset) {
                                            return null;
                                        }

                                        return (
                                            <g>
                                                <Rects.Inner
                                                    insetLeft={1}
                                                    strokeWidth={2}
                                                    stroke={theme.Border}
                                                    filterDatasets={(dataset) =>
                                                        dataset === highlightDataset
                                                    }
                                                />
                                            </g>
                                        );
                                    }}
                                />
                                <BarCursorLine
                                    name='ClickedBarCursorLine'
                                    points={clicked?.points ?? null}
                                    lineWidth={1}
                                    layer='svg-viz-bg'
                                    lineOffsetWidth={4}
                                />

                                <CategoryLegend
                                    xAlign='left'
                                    position='center'
                                    layer="html-before"
                                    direction="row"
                                    swatchShape="circle"
                                    absolutePosition={false}
                                    toggleVisibilityOnClick
                                />
                            </HistogramChart>
                        </VizkitProvider>
                    </Stack>
                </Stack>
            )}
        </div>
    );
}
