import * as OcgaProto from '@ocga/proto';
import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';

export const SESSION_GAME_LOGS_ERRORS = 'sessionGameLogsErrors';
const ERROR_REGEX = /(error|exception)/i;

export const useSessionGameLogsErrors = (gsId: string | undefined) => {
    const query = useQuery<any>({
        queryKey: [SESSION_GAME_LOGS_ERRORS, gsId],
        enabled: !!gsId,
        gcTime: 0, // These sessions are all historical
        queryFn: async () => {
            const result = await fetch(
                `/api/t2/${gsId}?${new URLSearchParams({
                    keywordFilters: 'error|exception',
                    messageTypes: [OcgaProto.MessageType.MessageType.LogEvent].join(','),
                    method: 'rest',
                })}`,
            );
            return await result.json();
        },
    });

    const errors = useMemo(() => {
        if (!query.data || !Array.isArray(query.data?.data)) {
            return [];
        }
        return query.data?.data
            .map((logJson: string) => {
                return JSON.parse(logJson);
            })
            .sort((a: any, b: any) => -a.Timestamp.localeCompare(b.Timestamp))
            .filter((log: any) => {
                const message = log.Message?.LogEvent?.Message;
                return message.match(ERROR_REGEX);
            });
    }, [query]);

    return {
        ...query,
        errors,
    };
};
