import { Card, Heading, Text, Tooltip, } from '@hawkins/components';
import styles from './TodayTile.module.css';
import clsx from 'clsx';

import { formatNumberShort, getDiffClassname, getDiffIcon, getDiffValue } from './helpers';

export interface TodayTileProps {
    title: string;
    subtitle: string;
    loading?: boolean;
    latestVal: number | undefined;
    diffVal: number | undefined;
    isPercent?: boolean;
}

const TodayTile = ({
    title,
    subtitle,
    loading,
    latestVal,
    diffVal,
    isPercent,
}: TodayTileProps) => {
    return (
        <Card className={styles.root} elevation={1}>
            <Card.Body className={styles.cardBody}>
                <div className={styles.row}>
                    <Text variant='body' level={2} bold component='div'>
                        {title}
                    </Text>
                    <Text variant='body' level={0} colorVariant='faded' component='div'>
                        {subtitle}
                    </Text>
                </div>
                <div className={styles.row}>
                    <Heading className={styles.heading} level={5} loading={loading}>
                        <Tooltip label={`${latestVal?.toLocaleString()}`}>
                            {`${formatNumberShort(latestVal)}${isPercent ? '%' : ''}`}
                        </Tooltip>
                    </Heading>
                    <div className={styles.diffHolder}>
                        {getDiffIcon(diffVal, 'standard')}
                        <Heading
                            className={clsx(styles.heading, getDiffClassname(diffVal))}
                            level={1}
                            loading={loading}
                        >
                            {`${getDiffValue(diffVal)}${isPercent ? '%' : ''}`}
                        </Heading>
                    </div>
                </div>
            </Card.Body>
        </Card>
    );
};

export default TodayTile;
